add(P('שני ראיונות נערכו בבתי המרואיינות בשעת ערב, אחרי שהילדים נרדמו, והשלישי בשיחת וידאו בשל מרחק ומשמרות. כל ראיון נפתח בהצגה עצמית, בהסבר על מטרת העבודה ובחתימה על טופס הסכמה מדעת. שאלת הפתיחה הייתה זהה בשלושתם: בקשה לתאר יום רגיל מרגע הקימה ועד ההירדמות. היא נבחרה משום שהיא קונקרטית, אינה מכוונת לתשובה רצויה ומזמינה סיפור רציף. אורך הראיונות נע בין שישים לתשעים דקות.'));
add(P('בניסוח השאלות התגלו שתי בעיות. שאלה ישירה על רגשות אשמה, שנשאלה בראיון הראשון בנוסח סגור, "את מרגישה אשמה?", קיבלה תשובה בת מילה אחת, והוחלפה בראיונות הבאים בניסוח פתוח שהניב חומר עשיר בהרבה. אחת המרואיינות אף דחתה את המילה אשמה והציעה במקומה אחריות, ובכך שינתה את שם התימה השנייה. הבעיה השנייה נגעה לשאלות על המשפחה המורחבת שנוסחו בלשון שיפוטית, כגון האם המשפחה מאפשרת לך ללמוד. שאלה כזאת מניחה מראש שהמשפחה היא מכשול, ונוסחה מחדש כבקשה לתאר מי נמצא בבית ביום לימודים.'));
add(P('שלושה אירועים ראויים לציון. בראיון הראשון התעוררה בתה של המרואיינת והשיחה נעצרה לכעשר דקות, ומשחזרה דיברה בגילוי לב רב יותר. בראיון השני בכתה המרואיינת כשתיארה בוקר שבו בנה נאחז בה בכניסה לגן, והמשיכה לפי בקשתה אחרי שההקלטה נעצרה. בראיון השלישי ביקשה המרואיינת להשמיט קטע שבו הזכירה סכסוך משפחתי, והקטע נמחק לפני הניתוח.'));
add(H2('2.4 שפת הראיון והתרגום'));
add(P('הראיונות נערכו בערבית מדוברת, לפי בחירת המרואיינות. הבחירה אינה טכנית: ראיון על חוויה אינטימית מתנהל בשפה שבה החוויה נחווית, ובקשה לדבר עברית הייתה מעבירה את המרואיינות לשפה שבה הן לומדות אך לא בהכרח מרגישות. התמלול נעשה תחילה בערבית, מילה במילה, ורק אחר כך תורגם לעברית.'));
add(P('התרגום הוא פעולה פרשנית ולא העברה נייטרלית, ולכן ננקטו שני צעדים: ביטויים שאין להם מקבילה מדויקת בעברית נשמרו בשפת המקור בתוך התמליל, בכתיב ערבי ובתעתיק עברי, ולצדם תרגום; ושתי המרואיינות שקראו את סיכום התימות התבקשו לאשר גם את תרגום הציטוטים שלהן. אחת מהן תיקנה תרגום אחד וטענה שהמילה שנבחרה חריפה מדי.'));
add(H2('2.5 ניתוח הנתונים'));
add(P('התמלול כלל את שאלות המראיינת, שתיקות וצחוק, מתוך תפיסה שהצורה שבה נאמר דבר היא חלק מן הנתון ולא עטיפה שלו (שקדי, 2003). הניתוח נערך בשיטת הניתוח התמטי הרפלקסיבי, לפי ששת השלבים שמתארות בראון וקלארק: היכרות עם החומר, קודים ראשוניים, חיפוש תימות, בחינה חוזרת, הגדרה ומתן שם, וכתיבה (Braun & Clarke, 2022).'));
add(P('בקידוד הפתוח נוצרו חמישים ושמונה קודים ראשוניים, כגון "שעות באוטו", "חשבון מול חמאתי" ו"לחשוב בערבית ולכתוב בעברית". הם קובצו לחמישה עשר אשכולות, ומהם לחמש תימות ולשלוש קטגוריות (נספח 3). חלק משמות התימות נלקחו מלשון המרואיינות, ובכללם שם התימה החמישית שנשאר בערבית. לחיזוק איכות הניתוח נשמר שביל ביקורת שתיעד כל החלטת קידוד, וסיכום התימות הוצג בפני שתיים מהמרואיינות. בגישה הרפלקסיבית איכות נמדדת בשקיפות ההכרעות הפרשניות ולא בהתאמה בין מקודדים (Braun & Clarke, 2022).'));
add(H2('2.6 סוגיות אתיות'));
add(P('כל המרואיינות חתמו על טופס הסכמה מדעת (נספח 4), שהוצג בעברית ובערבית וכלל את מטרת המחקר, ההסכמה להקלטה, ההתחייבות למחוק את קובץ האודיו לאחר התמלול, והזכות להפסיק או להשמיט דברים בכל שלב. זכות זו מומשה בראיון השלישי.'));
add(P('שמירת האנונימיות מציבה כאן קושי מיוחד: ביישוב שבו משפחות מכירות זו את זו, צירוף של תחום לימודים, מספר ילדים ומקום עבודה עלול לזהות אישה גם בלי שמה. ההכרעה הייתה לנקוב בשם היישוב בלבד, משום ששלושת היישובים מונים אלפי תושבים ולכן השם כשלעצמו אינו מזהה, ולטשטש כל פרט קטן ממנו: השמות הוחלפו בשמות בדויים, שמות השכונות, המשפחות המורחבות והמעסיקים הושמטו, וגילי הילדים עוגלו. בשתי העיירות הקטנות טושטשו גם מקום העבודה ושנת הלימודים המדויקת.'));
add(P('מעבר לנהלים הפורמליים עלו מה שגילמין וגילם מכנות רגעים בעלי חשיבות אתית, מצבים בלתי צפויים שאינם מכוסים בטופס ההסכמה ודורשים הכרעה בזמן אמת (Guillemin & Gillam, 2004). הרגע שבו מרואיינת בכתה היה רגע כזה, וההחלטה הייתה לעצור את ההקלטה ולהשאיר בידיה את ההכרעה. סוגיה נוספת נגעה לקרבת המראיינת לשדה, שהיא בת אותה חברה. אולמוס-וגה ואחרים מדגישים שעל החוקר לבחון כיצד מיקומו ויחסיו עם המשתתפים מעצבים את הידע שנוצר, במקום להעמיד פנים שהוא ניצב מחוץ למחקר (Olmos-Vega et al., 2023). הקרבה סייעה לפתיחות אך יצרה פיתוי להניח הבנה, ולכן נעשה מאמץ לבקש הבהרה גם על דברים שנשמעו מוכרים.'));

// ============ 4. findings ============
add(H1('3. ממצאים'));
add(P('הניתוח העלה חמש תימות. סדר הצגתן נע מן החוץ פנימה: מן הארגון הפיזי של היום, דרך העולם הפנימי, אל מעגלי המשפחה, המפגש עם המוסדות, ולבסוף המשמעות שמייחסות המרואיינות ללימודים.'));

add(H2('3.1 "היום מתחיל בחמש": זמן, מרחק ונסיעות'));
add(P('בשלושת הראיונות תואר היום לא כרצף שעות אלא כמלאי מוגבל שיש לחלק בין תובעים. אצל שתיים מהן נגרע מן המלאי נתח קבוע שאין עליו שליטה, הנסיעה.'));
add(P('סאמייה פתחה כך: "היום מתחיל בחמש, לפני שהם קמים, כי זה הזמן היחיד שהבית שקט. אני עושה שעה, ואז בשש הקטנה מתעוררת וזהו, נגמר."'));
add(Q('מהיישוב עד המכללה זה שעה וחצי בבוקר, אם אין פקק. אני יוצאת בשש וחצי ומגיעה לשיעור של שמונה. אחרי השיעור האחרון אני רצה לאוטו כדי להספיק לאסוף את הקטן, ובדרך חזרה זה שוב שעה וחצי. יש לי שלוש שעות ביום שאני יושבת באוטו. אנשים אומרים לי תלמדי בנסיעה, אני נוהגת. (רים)'));
add(P('הנסיעה אינה זמן פנוי ואינה זמן עבודה. היא נגרעת מן היום בלי להיחשב לאיש, ובשלושת הראיונות לא הוזכרה כשנשאלו על עומס אלא רק כשהתבקשו לתאר שעה אחר שעה. עיינא, שאין לה רישיון, מתארת תלות נוספת: "מי שמסיעה קובעת מתי יוצאים", ויום שבו ההסעה משתנה הוא יום לימודים אבוד. עיינא ניסחה את המסקנה: "השינה היא הדבר היחיד שאפשר לקצץ בו." כשהזמן מחולק כך, אף נוכחות אינה שלמה, וזו התימה הבאה.'));

add(H2('3.2 "לא אשמה, אחריות": פיצול הקשב והחשבון הפנימי'));
add(P('התימה השנייה עוסקת בנוכחות חלקית בכל מקום ובמנגנון ההצדקה הפנימי שמלווה אותה. שמה נלקח מתיקון שהציעה אחת המרואיינות למילה שהמראיינת השתמשה בה.'));
add(P('עיינא תיארה את הפיצול בקצרה: "אני יושבת בהרצאה וחושבת על הגן. אני בגן וחושבת על המבחן. אין רגע אחד שאני נמצאת רק במקום אחד." סאמייה ניסחה את החשש עצמו: "אם הייתי מפסיקה ללמוד הייתי אמא יותר טובה. אני יודעת שזה לא נכון, אבל אני חושבת את זה." הידיעה שהיא מייחסת לעצמה נתמכת בנתונים: זונטג מצא שתעסוקת אימהות לילדים מגיל שנה ומעלה אינה מתואמת שלילית עם הישגי ילדיהן במיצ"ב ולעיתים אף מתואמת עמם חיובית (זונטג, 2022). רים דחתה את המסגור הרגשי שהוצע לה: "לא אשמה. אחריות. אני אחראית, וזה לא אותו דבר."'));
add(P('ההבחנה אינה משחק מילים. סאמייה הסבירה אותה במונחים חברתיים: "אם משהו קורה לילד, אף אחד לא ישאל איפה היה אבא. ישאלו איפה הייתה האמא." מדובר פחות ברגש פרטי ויותר בעמדה שהחברה מקצה. עתאמנה מצאה בקרב אימהות פלסטיניות בישראל שהאחריות האימהית מובנית כמטלה מוסרית רחבה, המשתרעת גם על הישגי הילדים ועל שלומם הרגשי, ושהאימהות פועלות בתוכה כסוכנות ולא רק כקורבנות (Athamneh, 2024). המרואיינות כאן אינן מתארות את עצמן כנשברות תחת האחריות אלא כמנהלות אותה, ומכאן השאלה מי מסייע להן בפועל.'));

add(H2('3.3 "בלי חמאתי אין תואר": המשפחה המורחבת כתשתית וכחוב'));
add(P('התימה השלישית עוסקת בתשתית האנושית שמאפשרת את השילוב, ובמחיר הסמוי שהיא גובה.'));
add(P('סאמייה אמרה: "חמאתי (حماتي, חמותי) לוקחת אותם ארבעה ימים בשבוע. בלעדיה אין תואר, פשוט אין", ומיד הוסיפה: "אני מרגישה שאני חייבת לה. היא אף פעם לא אמרה מילה, זה אני." התמיכה מתוארת כהלוואה. היא מאפשרת את הלימודים ובו בזמן פותחת חשבון שאינו נסגר. גם אצל גרינבנק עלו מקורות התמיכה כתימה נפרדת בדברי האימהות ולא כרקע (גרינבנק, 2024). רים, שאין לה סידור קבוע, תיארה את הצד השני: "אין מעון לגיל שנה ביישוב שלי. אין. אז זה חמאתי או כלום."'));
add(P('נקודה שנייה עלתה בדבריה של עיינא: "בעלי עוזר המון, באמת." המילה עוזר חוזרת שלוש פעמים בראיון שלה, ואילו מתחלק או אחראי אינן מופיעות כלל. הפועל משמר את הנחת היסוד שהאחריות שייכת לאישה ושהגבר תורם לה מרצונו, והוא ביטוי לשוני מדויק לאותה אחריות אימהית שעתאמנה מתארת כמטלה שמוקצית לאם ולא נחלקת (Athamneh, 2024). ההיקף משתנה בין שלוש המרואיינות, אבל כיוון ההקצאה אינו משתנה.'));
add(P('נקודה שלישית נוגעת לכך שאותה משפחה שמחזיקה גם מתבוננת. רים ניסחה זאת כך: "שו ביחכו א-נאס (شو بيحكوا الناس, מה יגידו האנשים). זה לא משפט שמישהו אומר לך. זה כמו מזג אוויר, זה פשוט שם." התמיכה והפיקוח מגיעים מאותו מקור, ולכן אי אפשר לקבל את הראשונה ולהתנער מן השני. כשהמעגל המשפחתי אינו מספיק, נותר לפנות אל המוסדות.'));

add(H2('3.4 "המערכת לא בנויה בשבילנו": מרחק, שפה והתאמות שניתנות כטובה'));
add(P('התימה הרביעית עוסקת במפגש עם ארגונים, ובתלות בשיקול דעת אישי במקום בכללים.'));
add(Q('המבחן נקבע לשמונה בבוקר ביום שאין גן. שאלתי אם אפשר מועד אחר, אמרו לי שיש מועד ב\'. מועד ב\' זה לא פתרון, זה עונש, כי אז אני לומדת את זה פעמיים ומאבדת עוד שבוע. אף אחד לא חשב שיש כאלה שהבוקר שלהן לא פנוי. (רים)'));
add(P('לצד מועדי הבחינות עלה חסם שאינו מופיע בשום נוהל. עיינא תיארה אותו כך: "אני חושבת בערבית וכותבת בעברית. זה לוקח לי פי שניים זמן, וזה לא בגלל שאני לא מבינה את החומר." אבו-רביעה מצא שאצל סטודנטים בדווים תחושת המסוגלות בכתיבה ובדיבור בעברית נמוכה מזו שבהבנה, כלומר הקושי אינו בהבנת החומר אלא בהפקתו (Abu-Rabiah, 2025). כשחסם השפה נפגש עם שלוש שעות נסיעה ועם היעדר מעון ביישוב, הזמן שנותר ללימודים מצטמצם פעמיים.'));
add(P('סאמייה תיארה שני קצוות באותו סמסטר: "יש מרצה שאמרה לי תביאי אותה, שתשב מאחורה עם טאבלט. ויש מרצה שאמר לי שזה לא מעון." ההבדל אינו נעוץ במדיניות אלא באדם. מאחורי שני הקצוות עומדת הנחה אחת, שרנן-ברזילי מכנה תפיסת עבודה טוטלית: הלומדת נדרשת לזמינות מלאה, וכל מחויבות אחרת נחשבת חריגה (רנן-ברזילי, 2012). ההתאמות קיימות, אך הן ניתנות כטובה אישית ולא כזכות, ולכן אינן ניתנות לתכנון ולא לתביעה. זהו בדיוק מה שרפאלי ואחרות מתארות כפעולה משולבת של המישור המבני והמישור המשפחתי-מגדרי: המוסד אינו אוסר על הסטודנטית ללמוד, הוא פשוט אינו מתוכנן סביב האפשרות שיש לה ילד, וכל פתרון נותר עניין של מזל אישי (Refaeli et al., 2022). מכאן מתחדדת השאלה מדוע בכל זאת ממשיכות המרואיינות ללמוד.'));

add(H2('3.5 "בדי אכון אישי": התואר כזהות וכביטחון'));
add(P('התימה החמישית מציגה את הצד שאינו נזק, ושמה נשאר בערבית משום שהניסוח העברי מאבד ממנו.'));
add(P('עיינא אמרה: "בדי אכון אישי (بدي أكون إشي, אני רוצה להיות משהו). לא במקום אמא. ביחד עם." רים הוסיפה נימוק אחר לגמרי: "אם מחר אני לבד, אני צריכה לדעת שאני יכולה להחזיק את הילדים. תעודה זה ביטחון." סאמייה קשרה את הלימודים לדמות שהיא מציגה בפני ילדיה: "אני רוצה שהבת שלי תראה אותי לומדת." בביץ והדר מצאו בראיונות עם חמש עשרה נשות קריירה שהאם נתפסה כדמות המשפיעה ביותר על זהותן המקצועית (בביץ והדר, 2016).'));
add(Q('בהתחלה נרשמתי בשביל משכורת יותר טובה, בלי רומנטיקה. אבל אני יושבת בשיעור, פתאום מדברים על משהו ואני חושבת על זה שעתיים אחר כך, וזה החלק היחיד ביום שאני חושבת בו על משהו שהוא לא לוגיסטיקה. אז זה כבר לא רק הכסף. (סאמייה)'));
add(P('שלושת הנימוקים שונים: זהות, ביטחון כלכלי ומודל לילדה. משותף להם שהלימודים מתוארים בלשון בעלות ובלשון עתיד, בעוד ששאר תחומי החיים מתוארים בהווה דחוק. התפקיד הכפול הזה, מקור עומס ומקור זהות בבת אחת, הוא הממצא המרכזי שאליו מתייחס הדיון.'));

// ============ 5. discussion ============
add(H1('4. דיון'));
add(P('הממצאים מלמדים ששאלת השילוב אינה שאלה של ניהול זמן. שלוש המרואיינות מנהלות את זמנן היטב ובכל זאת מתארות מחסור קבוע. רפאלי ואחרות הראו שהחסמים בדרכן של נשים בדוויות צעירות פועלים בו זמנית במישור המבני ובמישור המשפחתי (Refaeli et al., 2022), והממצאים כאן מוסיפים לכך רכיב שאינו נכלל בדרך כלל בחישוב: המרחק. שלוש שעות נסיעה ביום אינן קונפליקט בין תפקידים, הן גריעה מן היממה, והן נובעות מפריסת מוסדות ההשכלה הגבוהה ומן התחבורה הציבורית ולא מהחלטה של האישה או של משפחתה.'));
add(P('התימה השנייה מבהירה מדוע העומס נחווה כאחריות ולא ככשל מערכתי. עתאמנה תיארה את האחריות האימהית בחברה הפלסטינית בישראל כמטלה מוסרית רחבה שהאם מבצעת מתוך סוכנות ולא רק ככפייה (Athamneh, 2024), וזו בדיוק ההבחנה שעשתה אחת המרואיינות כשדחתה את המילה אשמה. אשמה מניחה כישלון, אחריות מניחה תפקיד. אין כאן נשים שמבקשות שיצילו אותן, אלא נשים שמבקשות שהתנאים ישתנו. החשש שהלימודים פוגעים בילדים אינו נתמך בנתונים הישראליים (זונטג, 2022), ולכן מדובר בעמדה חברתית שהופנמה ולא במסקנה מן המציאות.'));
add(P('הממצא על החמות מוסיף נדבך שאינו מופיע בספרות על החסמים המשפחתיים, שנוטה לתאר את המשפחה כמי שמתירה או מונעת (Refaeli et al., 2022). כאן המשפחה אינה מתירה ואינה מונעת, היא מבצעת: הגורם שמאפשר את הלימודים בפועל הוא אישה אחרת מן הדור הקודם. התמיכה עוברת בין נשים, וכך גם הפיקוח, ושתיהן מגיעות מאותו מקור.'));
add(P('ההתאמות הניתנות כטובה אישית ולא כזכות ממחישות את אותה נקודה. כשמצטרף אליהן חסם השפה, שבו הקושי אינו בהבנה אלא בהפקה (Abu-Rabiah, 2025), מתברר שאין טעם לשאול אם המכשול הוא המכללה או הבית: שניהם פועלים על אותה שעה ביום. התאמה שאינה כתובה אינה ניתנת לתכנון, וסטודנטית שנאלצת לבקש אותה מחדש מכל מרצה משלמת מחיר נוסף בזמן ובכבוד.'));
add(P('התימה החמישית מסייגת את התמונה. ניסוחה של עיינא, "לא במקום אמא, ביחד עם", הוא בדיוק מה שרנן-ברזילי מכנה רב-ממדיות: הכרה בכמה ממדים בחיי אדם ומתן משקל ממשי לכל אחד מהם, במקום הכרעה ביניהם (רנן-ברזילי, 2012). כלומר קונפליקט והעשרה מתקיימים אצל אותן נשים בעת ובעונה אחת. מסגור השילוב כבעיה בלבד מחמיץ אפוא חלק מהותי מן החוויה, ומדיניות שתבקש להקל באמצעות צמצום דרישות עלולה לפגוע דווקא במה שמחזיק אותן.'));
add(P('מכאן חמש מסקנות יישומיות: ריכוז ימי הלימוד של סטודנטיות מן הנגב בשניים או שלושה ימים רצופים; פרסום לוח בחינות בתחילת הסמסטר והימנעות משיבוץ בחינות בבוקר מוקדם ביום שבו מסגרות החינוך סגורות; נוהל מוסדי כתוב להתאמות לסטודנטים הורים במקום שיקול דעתו של המרצה; סיוע קבוע בכתיבה אקדמית בעברית לדוברות ערבית ולא סדנה חד פעמית; ומרחב עמיתים לסטודנטיות אימהות מן החברה הבדווית. מגבלות העבודה ברורות: שלוש מרואיינות אינן מדגם, כולן נשואות, כולן מיישובים מוכרים, וכולן בחרו להשתתף. נשים מכפרים לא מוכרים ונשים שנשרו מן הלימודים אינן מיוצגות כאן, ודווקא סיפורן היה עשוי לשנות את התמונה.'));

// ============ 6. process reflection ============
add(H1('5. תהליך ביצוע העבודה'));
add(P('בחירת הנושא לא הייתה ניטרלית, והיא נבחרה מתוך קרבה. הספרות המתודולוגית מציעה לכך תשובה: הרפלקסיביות אינה ניסיון לנטרל את החוקרת אלא סדרה של פרקטיקות שבהן היא בוחנת כיצד הסובייקטיביות שלה מעצבת את המחקר (Olmos-Vega et al., 2023). לכן נכתב לפני הראיונות מסמך קצר של הנחות מוקדמות, ובו ההנחה שהמרואיינות יתארו בעיקר לחץ משפחתי. ההנחה התבררה כשגויה ברובה: המשפחה עלתה בעיקר כתשתית מאפשרת, והחסמים החריפים ביותר שתוארו היו מוסדיים, מרחק, שפה ומועדי בחינות.'));
add(P('הראיון הראשון נוהל בצורה מגושמת, עם רשימת שאלות ועם נטייה למלא כל שתיקה. בספרות על הראיון האיכותני מודגש שהמראיין נדרש לדבר פחות ולהקשיב יותר, ושהשתיקה היא כלי ולא כישלון (שקדי, 2003). בראיונות הבאים נעשה מאמץ לספור שלוש שניות לפני כל תגובה, והמרואיינות הגיעו מעצמן לחומר שלא נשאלו עליו.'));
add(P('ההכרעה המתודולוגית המשמעותית ביותר נגעה לשפה. תרגום מערבית מדוברת לעברית אקדמית משטח את הטקסט, ומילים טעונות מאבדות את משקלן. הביטוי "שו ביחכו א-נאס" הוא דוגמה טובה: התרגום "מה יגידו האנשים" נשמע כמו דאגה קטנה, בעוד שבמקור מדובר במנגנון פיקוח יומיומי. לכן הוחלט לשמר ביטויים כאלה בשפת המקור בתוך התמליל ולצרף להם תרגום, ולא להסתפק בעברית. שם התימה החמישית נשאר בערבית מאותה סיבה.'));
add(P('בשלב הקידוד עלתה התלבטות ממשית. האמירה של סאמייה, "אני מרגישה שאני חייבת לה, היא אף פעם לא אמרה מילה, זה אני", התאימה לשתי קטגוריות: רשת תמיכה ואחריות פנימית. השיוך לתימת המשפחה נבחר משום שההקשר היה תיאור של סידור הילדים, ומשום שהחוב מתקיים כלפי אדם מסוים ולא כלפי אידיאל מופשט. התלבטות דומה נגעה לשאלה אם הנסיעות הן תימה בפני עצמה, והן שולבו בתימת הזמן משום ששלוש המרואיינות דיברו עליהן בתוך תיאור היום. שתי ההחלטות והנימוקים תועדו בשביל הביקורת.'));
add(P('הצגת סיכום התימות בפני שתי מרואיינות שינתה שני דברים: אחת תיקנה תרגום, והשנייה העירה שהכותרת שהוצעה לתימה השנייה, שכללה את המילה אשמה, אינה מתארת אותה. ההערה לא נוספה כהסתייגות בשוליים אלא שינתה את שם התימה. זו הייתה הלמידה המרכזית: ניתוח איכותני אינו איסוף ציטוטים אלא רצף הכרעות, והשקיפות לגביהן מבדילה בין ניתוח לבין רושם אישי (שקדי, 2003; Braun & Clarke, 2022).'));

